//! Cargo-driven `rapps.exe` link, generated by tools/cargo_cell_gen.py
//! from the cmake link it replaces.
//! The body is rapps-rust; reactos-link builds the PE.

use reactos_link::{Linker, ModuleKind, MsvcrtexKind};
use std::env;

fn main() {
    let arch = env::var("CARGO_CFG_TARGET_ARCH").expect("CARGO_CFG_TARGET_ARCH");
    let (target_json, entry) = match arch.as_str() {
        "x86" => ("i686-pc-windows-gnu", "_wWinMainCRTStartup"),
        "x86_64" => ("x86_64-pc-windows-gnu", "wWinMainCRTStartup"),
        "aarch64" => ("aarch64-pc-windows-gnullvm", "wWinMainCRTStartup"),
        o => panic!("rapps-cargo: unsupported arch {o}"),
    };

    let link_order: &[&str] = match arch.as_str() {
        "x86" => &["body", "engine:conutils", "engine:uuid", "engine:c:cpprt", "engine:c:minizip", "engine:c:zlib", "import:advapi32", "import:comctl32", "import:gdi32", "import:wininet", "import:crypt32", "import:cryptui", "import:user32", "import:shell32", "import:shlwapi", "import:ole32", "import:setupapi", "import:gdiplus", "import:msvcrt", "import:kernel32", "import:ntdll", "engine:conutils_rust", "toolchain:libc++.a", "toolchain:libc++abi.a", "toolchain:libunwind.a", "toolchain:libwinpthread.a", "engine:c:stdc++compat", "import:kernel32_vista", "engine:pseh", "engine:chkstk", "engine:oldnames"],
        "x86_64" => &["body", "engine:conutils", "engine:uuid", "engine:c:cpprt", "engine:c:minizip", "engine:c:zlib", "import:advapi32", "import:comctl32", "import:gdi32", "import:wininet", "import:crypt32", "import:cryptui", "import:user32", "import:shell32", "import:shlwapi", "import:ole32", "import:setupapi", "import:gdiplus", "import:msvcrt", "import:kernel32", "import:ntdll", "engine:conutils_rust", "toolchain:libc++.a", "toolchain:libc++abi.a", "toolchain:libunwind.a", "toolchain:libwinpthread.a", "engine:c:stdc++compat", "import:kernel32_vista", "engine:pseh", "engine:oldnames"],
        "aarch64" => &["body", "engine:conutils", "engine:uuid", "engine:c:cpprt", "engine:c:minizip", "engine:c:zlib", "import:advapi32", "import:comctl32", "import:gdi32", "import:wininet", "import:crypt32", "import:cryptui", "import:user32", "import:shell32", "import:shlwapi", "import:ole32", "import:setupapi", "import:gdiplus", "import:msvcrt", "import:kernel32", "import:ntdll", "engine:conutils_rust", "toolchain:libc++.a", "toolchain:libc++abi.a", "toolchain:libunwind.a", "toolchain:libwinpthread.a", "engine:c:stdc++compat", "import:kernel32_vista", "engine:pseh", "engine:chkstk", "engine:oldnames"],
        _ => unreachable!(),
    };

    // The module's part of cmake's windres command; reactos-link adds what every
    // module shares from reactos-link/cflags/rc.<arch>.flags (Linker::rc).
    let rc_includes: &[&str] = &[
        "@build/base/applications/rapps",
        "base/applications/rapps",
        "@std",
        "vendor/opengl-headers/include",
        "vendor/libdxg/include",
        "base/applications/rapps/include",
        "sdk/lib/cryptlib",
        "sdk/lib/conutils",
        "vendor/zlib/contrib",
        "vendor/zlib/contrib/minizip",
        "vendor/zlib/include",
        "sdk/lib/pseh/include",
    ];
    let rc_flags: &[&str] = &[];
    let rc_defines: &[&str] = &[
        "UNICODE",
        "USE_CERT_PINNING",
        "WINVER=0x502",
        "_CRT_DECLARE_NONSTDC_NAMES=1",
        "_CRT_NONSTDC_NO_DEPRECATE",
        "_DLL",
        "_UNICODE",
        "_WIN32_WINNT=0x502",
        "__USE_CRTIMP",
    ];

    // cmake built the body with these RUSTFLAGS (its rust_staticlib_variant ENV).
    let body_rustflags = match arch.as_str() {
        "x86" => Some("-C target-feature=+sse,+sse2"),
        _ => None,
    };
    let mut link = Linker::new(target_json);
    if let Some(flags) = body_rustflags {
        link = link.rust_build_rustflags(flags);
    }
    link
        .rust_staticlib("rapps-rust")
        .c_from_compile_db("rapps_shims", &["base/applications/rapps/rust_cohab_stub.cpp"])
        .rc("base/applications/rapps/rapps.rc", rc_includes, rc_flags, rc_defines)
        .import_lib("dll/win32/advapi32/advapi32.spec", "advapi32.dll", "advapi32")
        .import_lib("dll/win32/comctl32/comctl32.spec", "comctl32.dll", "comctl32")
        .import_lib("win32ss/gdi/gdi32/gdi32.spec", "gdi32.dll", "gdi32")
        .import_lib("dll/win32/wininet/wininet.spec", "wininet.dll", "wininet")
        .import_lib("dll/win32/crypt32/crypt32.spec", "crypt32.dll", "crypt32")
        .import_lib("dll/win32/cryptui/cryptui.spec", "cryptui.dll", "cryptui")
        .import_lib("win32ss/user/user32/user32.spec", "user32.dll", "user32")
        .import_lib("dll/win32/shell32/shell32.spec", "shell32.dll", "shell32")
        .import_lib("dll/win32/shlwapi/shlwapi.spec", "shlwapi.dll", "shlwapi")
        .import_lib("dll/win32/ole32/ole32.spec", "ole32.dll", "ole32")
        .import_lib("dll/win32/setupapi/setupapi.spec", "setupapi.dll", "setupapi")
        .import_lib("dll/win32/gdiplus/gdiplus.spec", "gdiplus.dll", "gdiplus")
        .import_lib("dll/win32/msvcrt/msvcrt.spec", "msvcrt.dll", "msvcrt")
        .import_lib("dll/win32/kernel32/kernel32.spec", "kernel32.dll", "kernel32")
        .import_lib("dll/ntdll/def/ntdll.spec", "ntdll.dll", "ntdll")
        .import_lib("dll/win32/kernel32/kernel32_vista/kernel32_vista.spec", "kernel32_vista.dll", "kernel32_vista")
        // The body, import libs and static libs in cmake's link order: the first
        // to define a symbol wins. cmake-built ones are reused until each has a
        // cargo home; `engine:` ones reactos-link builds.
        .link_order(link_order)
        .msvcrtex_crt(MsvcrtexKind::ExeWide)
        .link(ModuleKind::Win32Exe {
            entry: entry.into(),
            subsystem: "windows:5.01".into(),
        });
}
